{"content":"from collections import Counter


def _hand_rank(hand):
    """Return a lexicographically comparable rank for a five-card hand."""
    cards = hand.split()
    values = {str(value): value for value in range(2, 11)}
    values.update(J=11, Q=12, K=13, A=14)
    ranks = sorted((values[card[:-1]] for card in cards), reverse=True)
    groups = sorted(
        ((count, rank) for rank, count in Counter(ranks).items()),
        reverse=True,
    )
    counts = tuple(count for count, _ in groups)
    grouped_ranks = tuple(rank for _, rank in groups)
    flush = len({card[-1] for card in cards}) == 1

    straight_high = 0
    if ranks == [14, 5, 4, 3, 2]:
        straight_high = 5
    elif len(groups) == 5 and ranks[0] - ranks[-1] == 4:
        straight_high = ranks[0]

    if flush and straight_high:
        return (8, straight_high)
    if counts == (4, 1):
        return (7,) + grouped_ranks
    if counts == (3, 2):
        return (6,) + grouped_ranks
    if flush:
        return (5,) + tuple(ranks)
    if straight_high:
        return (4, straight_high)
    if counts == (3, 1, 1):
        return (3,) + grouped_ranks
    if counts == (2, 2, 1):
        return (2,) + grouped_ranks
    if counts == (2, 1, 1, 1):
        return (1,) + grouped_ranks
    return (0,) + tuple(ranks)


def best_hands(hands):
    """Return all strongest hands, preserving their input strings and order."""
    ranked_hands = [(hand, _hand_rank(hand)) for hand in hands]
    if not ranked_hands:
        return []
    best_rank = max(rank for _, rank in ranked_hands)
    return [hand for hand, rank in ranked_hands if rank == best_rank]
